mapper.select:
SELECT id, form_id, form_key, name, field_key, field_type, internal_key, is_system,
       required, default_value, options, sort, visible, editable, section_name, section_sort,
       organization_id, create_user, update_user, create_time, update_time
FROM module_field
WHERE form_key = #{formKey}
  AND field_key = #{fieldKey}
  AND organization_id = #{orgId}
LIMIT 1

mapper.delete:
DELETE FROM module_field
WHERE form_key = #{formKey}
  AND organization_id = #{orgId}

